insert into message_templates (id, name, category, channel, subject, body, is_active, usage_count) values
  ('dddddddd-dddd-dddd-dddd-000000000001', 'Welcome to the Team', 'welcome', 'email', 'Welcome to the Team', 'Hi {{first_name}}, congratulations again on accepting your offer for the {{role}} role. We are excited to have you join us on {{joining_date}}. Over the next few weeks we will share onboarding details, documentation steps, and an introduction to your manager. Reach out any time.', true, 142),
  ('dddddddd-dddd-dddd-dddd-000000000002', 'Document Submission Reminder', 'documentation_reminder', 'email', 'Documents pending for your onboarding', 'Hi {{first_name}}, a quick reminder to upload the pending documents (Aadhaar, PAN, address proof, bank details) on the candidate portal. Let us know if you need any help.', true, 118),
  ('dddddddd-dddd-dddd-dddd-000000000003', 'Pre-Joining Check-in', 'pre_joining_checkin', 'whatsapp', null, 'Hi {{first_name}}, checking in before your joining date on {{joining_date}}. How are the preparations going? Happy to help with relocation, accommodation, or any other questions.', true, 87),
  ('dddddddd-dddd-dddd-dddd-000000000004', 'Manager Introduction', 'manager_intro', 'email', 'Introduction to your hiring manager', 'Hi {{first_name}}, we would like to set up a short call with {{manager_name}}, your hiring manager, so you can connect before day one. Please share a few time slots that work for you.', true, 73),
  ('dddddddd-dddd-dddd-dddd-000000000005', 'Joining Day Instructions', 'joining_instructions', 'email', 'Your first day details', 'Hi {{first_name}}, here are the details for your first day on {{joining_date}}: reporting time, office address, the documents to carry, and your point of contact.', true, 54),
  ('dddddddd-dddd-dddd-dddd-000000000006', 'General Follow-up', 'custom', 'email', 'Following up', 'Hi {{first_name}}, just following up on our last conversation. Let me know if there is anything you need from our side.', true, 39);
