-- seed.sql
-- Post-Offer Engagement HRMS: seed data (Phase 1).
-- Generated deterministically. Safe to run once against an empty database
-- created by supabase/migrations/001_initial_schema.sql.
-- All dates are relative to current_date / now() at insert time.
--
-- Order: recruiters -> message_templates -> candidates (with NULL
-- current_risk_assessment_id) -> journey steps -> risk_assessments ->
-- UPDATE candidates.current_risk_assessment_id -> remaining child tables.

begin;

-- recruiters: 6 rows

-- message_templates: 6 rows

-- candidates: 55 rows

-- candidate_journey_steps: 330 rows

-- risk_assessments: 121 rows

-- resolve the circular reference: point each candidate at its current risk assessment
update candidates c
   set current_risk_assessment_id = ra.id
  from risk_assessments ra
 where ra.candidate_id = c.id
   and ra.is_current;

-- engagement_events: 375 rows

-- conversations: 82 rows

-- messages: 403 rows

-- candidate_notes: 96 rows

-- tasks: 118 rows

-- documents: 220 rows

-- ai_recommendations: 96 rows

commit;
